window.REPORT_PRELOAD_CACHE["CMCSA.html"] = {"version":"3a3acbca3efcd6dd4d95bb04825cb1903f5dc30b921af37ee591aeb0808c3c25","html":"html_content = \"\"\"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n <meta charset=\"Chart.UTF-8\" />\n <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n <title>康卡斯特 Comcast (NASDAQ: CMCSA) 深度研究报告：从传统有线电视巨头到高带宽连接与内容娱乐生态重估</title>\n <!-- Tailwind CSS -->\n <script src=\"https://cdn.tailwindcss.com\"></script>\n <!-- Chart.js -->\n <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n <!-- Google Fonts: Inter + Noto Sans SC + JetBrains Mono -->\n <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n <script>\n tailwind.config = {\n darkMode: 'class',\n theme: {\n extend: {\n fontFamily: {\n sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n mono: ['JetBrains Mono', 'monospace'],\n },\n colors: {\n navy: {\n 950: '#070B14',\n 900: '#0F172A',\n 800: '#1E293B',\n 700: '#334155',\n },\n cmcblue: {\n 400: '#38BDF8',\n 500: '#0066CC',\n 600: '#004C99',\n },\n accent: {\n 500: '#3B82F6',\n 600: '#2563EB',\n },\n teal: {\n 500: '#06B6D4',\n 600: '#0891B2',\n }\n }\n }\n }\n }\n </script>\n\n <style>\n ::-webkit-scrollbar {\n width: 6px;\n height: 6px;\n }\n ::-webkit-scrollbar-track {\n background: transparent;\n }\n ::-webkit-scrollbar-thumb {\n background: #94A3B8;\n border-radius: 3px;\n }\n .dark ::-webkit-scrollbar-thumb {\n background: #475569;\n }\n\n @media print {\n #sidebar, #mobile-header, #theme-toggle-btn, .no-print {\n display: none !important;\n }\n main {\n margin-left: 0 !important;\n padding: 0 !important;\n }\n section {\n break-inside: avoid;\n }\n }\n\n .report-card {\n transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n }\n .report-card:hover {\n transform: translateY(-2px);\n }\n\n .nav-link.active {\n background: linear-gradient(90deg, rgba(0, 102, 204, 0.22) 0%, rgba(6, 182, 212, 0.06) 100%);\n border-left: 3px solid #0066CC;\n color: #FFFFFF;\n font-weight: 600;\n }\n </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-cmcblue-500 selection:text-white transition-colors duration-200\">\n\n <!-- 顶部全局阅读进度条 -->\n <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-cmcblue-500 via-emerald-400 to-teal-500 w-0 transition-all duration-150\"></div>\n </div>\n\n <!-- 移动端顶部导航栏 -->\n <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n <div class=\"flex items-center space-x-2.5\">\n <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-cmcblue-500 to-cmcblue-600 flex items-center justify-center font-extrabold text-white shadow\">\n CM\n </div>\n <div>\n <div class=\"text-[11px] text-cmcblue-400 font-semibold tracking-wider uppercase\">NASDAQ: CMCSA · Equity Research</div>\n <div class=\"text-sm font-bold leading-tight\">康卡斯特 Comcast 深度研究报告</div>\n </div>\n </div>\n <div class=\"flex items-center space-x-2\">\n <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-slate-300\" aria-label=\"切换阅读主题\">\n <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n </button>\n <button id=\"mobile-menu-btn\" onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-white\" aria-label=\"打开目录\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n </button>\n </div>\n </header>\n\n <!-- 移动端折叠抽屉菜单 -->\n <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n <div>\n <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n <span class=\"font-bold text-white text-base\">CMCSA 研报目录导航</span>\n <button onclick=\"toggleMobileMenu()\" class=\"p-1.5 rounded-lg text-slate-400 hover:text-white\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\"/></svg>\n </button>\n </div>\n <ul class=\"mt-4 space-y-1.5 text-sm\">\n <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">00. 执行摘要与核心指标</a></li>\n <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">01. 业务与收入架构</a></li>\n <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">02. 行业地位与四重护城河</a></li>\n <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">03. 同行竞争格局横向对比</a></li>\n <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">04. 财务健康与估值体系</a></li>\n <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">05. 投资决策与风险配置</a></li>\n <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">06. 季度跟踪 KPI 核查清单</a></li>\n </ul>\n </div>\n <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n <p>全球电信与媒体娱乐研究组</p>\n <p class=\"mt-1\">数据基准：2026年11月 (Q3 2026 / FY26)</p>\n </div>\n </nav>\n </div>\n\n <!-- 桌面端左侧固定侧边导航栏 (宽 280px) -->\n <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n <div>\n <!-- 机构品牌头 -->\n <div class=\"p-5 border-b border-slate-800/80\">\n <div class=\"flex items-center space-x-3\">\n <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-cmcblue-500 to-cmcblue-600 flex items-center justify-center text-white font-extrabold text-base shadow-lg shadow-cmcblue-500/25\">\n CMCSA\n </div>\n <div>\n <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-cmcblue-400 bg-cmcblue-500/15 px-2 py-0.5 rounded\">NASDAQ: CMCSA</span>\n <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">康卡斯特深度研报</h2>\n </div>\n </div>\n <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n 全球宽带连接与内容娱乐巨头 · 高现金流回报与严重价值低估标的\n </p>\n </div>\n\n <!-- 股票实时快照徽章 -->\n <div class=\"px-5 py-3 bg-navy-950/70 border-b border-slate-800/80 space-y-1.5 text-xs\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">当前参考股价</span>\n <span class=\"font-mono font-bold text-white\">$25.16 <span class=\"text-cmcblue-400\">(DCF估值 $45.66)</span></span>\n </div>\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">Q3 2026 营收</span>\n <span class=\"font-mono font-bold text-teal-400\">$29.3B <span class=\"text-slate-400\">(EPS $1.07)</span></span>\n </div>\n <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n <span class=\"text-slate-400\">预期股息率</span>\n <span class=\"font-mono font-bold text-cmcblue-400\">~5.25% (极具吸引力)</span>\n </div>\n </div>\n\n <!-- 六个核心章节目录导航 -->\n <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-310px)]\">\n <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">核心研究章节</div>\n <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-cmcblue-400 mr-2\">00</span>执行摘要与核心指标</span>\n </a>\n <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>业务与收入架构</span>\n </a>\n <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>行业地位与四重护城河</span>\n </a>\n <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>同行竞争格局横向对比</span>\n </a>\n <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>财务健康与估值体系</span>\n </a>\n <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>投资决策与风险配置</span>\n </a>\n <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>季度跟踪 KPI 核查清单</span>\n </a>\n </nav>\n </div>\n </div>\n\n <!-- 侧边栏底部工具栏 -->\n <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-xs text-slate-400\">阅读模式切换</span>\n <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-xs font-medium text-slate-200 border border-slate-700 transition\">\n <svg class=\"w-3.5 h-3.5 text-amber-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n <svg class=\"w-3.5 h-3.5 text-cmcblue-400 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <span class=\"dark:hidden\">深色护眼模式</span>\n <span class=\"hidden dark:inline\">机构亮色模式</span>\n </button>\n </div>\n <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-cmcblue-500 hover:bg-cmcblue-600 text-white text-xs font-extrabold transition shadow-sm\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n <span>打印 / 导出 PDF 研报</span>\n </button>\n </div>\n </aside>\n\n <!-- 主内容区 -->\n <main class=\"lg:ml-[280px] min-h-screen\">\n <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n <!-- =========================================================\n 00. Hero 研报封面区与执行摘要\n ========================================================= -->\n <section id=\"sec-exec\" class=\"scroll-mt-20\">\n <!-- 顶部研报元数据标签栏 -->\n <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n <div class=\"flex flex-wrap items-center gap-2\">\n <span class=\"px-2.5 py-1 rounded-md bg-cmcblue-500/15 text-cmcblue-600 dark:text-cmcblue-400 font-bold border border-cmcblue-500/30\">评级：审慎增持 / 深度价值与高自由现金流标的</span>\n <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">周期：2026 宽带防御、Peacock 减亏与娱乐生态转型期</span>\n </div>\n <div class=\"flex items-center space-x-3 font-mono\">\n <span>覆盖时间：2026年11月</span>\n <span>NASDAQ: CMCSA</span>\n </div>\n </div>\n\n <!-- Hero 标题卡片 -->\n <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n <div class=\"absolute inset-0 opacity-10 pointer-events-none\" style=\"background-image: radial-gradient(#0066CC 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n <div class=\"relative z-10\">\n <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-cmcblue-500/20 border border-cmcblue-500/40 text-cmcblue-400 text-xs font-semibold mb-4\">\n <span class=\"w-2 h-2 rounded-full bg-cmcblue-400 animate-pulse\"></span>\n <span>CORE THESIS · 住宅宽带与无线移动（Xfinity Mobile）双轮驱动 × DCF 估值内在价值 $45.66（当前股价 ~$25.16，安全边际超 45%）</span>\n </div>\n <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n 康卡斯特 Comcast Corporation (NASDAQ: CMCSA) 深度研究报告：从传统有线电视巨头到高带宽连接与内容娱乐生态重估\n </h1>\n <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n 康卡斯特作为全球领先的电信与媒体娱乐巨头，正处于传统有线电视向高带宽连接与流媒体娱乐全面转型的关键期。Q3 2026 营收保持平稳（<strong class=\"text-white\">$29.3B</strong>），调整后每股收益（EPS）达 <strong class=\"text-cmcblue-400\">$1.07</strong>（超市场预期 8.6%），调整后 EBITDA 达 <strong class=\"text-teal-400\">$9.11B</strong>（利润率 31.1%）。\n 面对光纤与固定无线接入（FWA）的竞争挑战，公司无线业务用户破千万（10.6M），Peacock 付费订阅达 4,800 万。在多重悲观预期下，其股价较历史高位跌幅显著，多项现金流与 DCF 估值模型显示其内在价值达 <strong class=\"text-emerald-400\">$45.66</strong>，安全边际极具吸引力。\n </p>\n\n <!-- 核心投资结论高亮条 -->\n <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">DCF 模型显示深度低估</div>\n <div class=\"text-white font-semibold\">基于盈利的 DCF 估值内在价值达 $45.66（当前市价 $25.16，安全边际 45.8%）</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">无线移动业务高速成长</div>\n <div class=\"text-cmcblue-400 font-semibold\">国内无线业务新增 36.8 万用户，总用户数达 1,060 万，构成强劲的防御性捆绑</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">超高股息与现金流创造</div>\n <div class=\"text-teal-400 font-semibold\">预期股息率达 5.25%，Q3 自由现金流达 $4.2B，股东资本回报力度强劲</div>\n </div>\n </div>\n </div>\n </div>\n\n <!-- 4个核心 KPI 卡片 -->\n <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n <!-- KPI 1 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>Q3 2026 营业收入</span>\n <span class=\"p-1.5 rounded-lg bg-cmcblue-500/15 text-cmcblue-600 dark:text-cmcblue-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$29.3B</span>\n <span class=\"text-xs font-bold text-cmcblue-600 dark:text-cmcblue-400 bg-cmcblue-500/15 px-2 py-0.5 rounded\">符合预期</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 尽管面临 Versant剥离与 Sky 德国出售带来的基数调整，总体营收保持平稳，符合华尔街一致预期。\n </p>\n </div>\n\n <!-- KPI 2 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>Q3 调整后每股收益 (EPS)</span>\n <span class=\"p-1.5 rounded-lg bg-accent-500/10 text-accent-600 dark:text-accent-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M5 12h14M5 12a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v4a2 2 0 01-2 2M5 12a2 2 0 00-2 2v4a2 2 0 002 2h14a2 2 0 002-2v-4a2 2 0 00-2-2m-2-4h.01M17 16h.01\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$1.07</span>\n <span class=\"text-xs font-bold text-accent-600 dark:text-accent-400 bg-accent-500/10 px-2 py-0.5 rounded\">超预期 +8.6%</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 调整后每股收益达 $1.07，超出分析师共识预期的 $0.98，展现出卓越的成本管控与利润弹性。\n </p>\n </div>\n\n <!-- KPI 3 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>自由现金流 (Free Cash Flow)</span>\n <span class=\"p-1.5 rounded-lg bg-teal-500/10 text-teal-600 dark:text-teal-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$4.2B</span>\n <span class=\"text-xs font-bold text-teal-600 dark:text-teal-400 bg-teal-500/10 px-2 py-0.5 rounded\">FCF 利润率 14.4%</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 单季自由现金流高达 $42 亿美元，强大的现金创造力持续支持高额股息分红与股份回购。\n </p>\n </div>\n\n <!-- KPI 4 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>DCF 内在价值 vs 当前市价</span>\n <span class=\"p-1.5 rounded-lg bg-emerald-500/10 text-emerald-600 dark:text-emerald-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$45.66</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/10 px-2 py-0.5 rounded\">安全边际 +45.8%</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 机构 DCF 盈利模型测算其内在价值达 $45.66，相比 $25.16 的市价呈现极佳的估值安全边际。\n </p>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 一、 业务与收入架构 (Business & Revenue Architecture)\n ========================================================= -->\n <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-cmcblue-600 dark:text-cmcblue-400\">Section 01 · Business & Revenue Architecture</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 业务与收入架构：连接与平台（Connectivity & Platforms）与内容娱乐双引擎</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">Q3 2026 总营收 $29.3B · 住宅连接与内容体验协同</span>\n </div>\n\n <!-- 交互式 Chart.js 双视图切换面板 -->\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n <!-- 左侧：双视图图表 -->\n <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\" id=\"biz-chart-title\">2023–2026 核心板块营收演进与贡献结构</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\" id=\"biz-chart-sub\">Connectivity & Platforms 与 Content & Experiences 双核驱动</p>\n </div>\n <div class=\"inline-flex rounded-lg bg-slate-100 dark:bg-navy-800 p-1 text-xs no-print\">\n <button onclick=\"switchBizChart('revenue')\" id=\"btn-chart-rev\" class=\"px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-cmcblue-600 dark:text-cmcblue-400 shadow-sm transition\">视图A：板块营收演进</button>\n <button onclick=\"switchBizChart('segments')\" id=\"btn-chart-seg\" class=\"px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition\">视图B：Q3 营收与利润构成</button>\n </div>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"bizArchitectureChart\"></canvas>\n </div>\n </div>\n\n <!-- 右侧：结构性拆解核心洞察 -->\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">商业架构三大结构性支柱</h3>\n <ul class=\"space-y-4 text-sm\">\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-cmcblue-500/15 text-cmcblue-600 dark:text-cmcblue-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">住宅连接与平台（Residential Connectivity）</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 核心宽带与无线业务。尽管面对光纤和 FWA 竞争导致国内住宅宽带用户净减少 14.4 万，但 Xfinity Mobile 表现亮眼（新增 36.8 万无线线缆用户，总数达 1,060 万），形成强大的“宽带+无线”防守组合。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-teal-500/15 text-teal-600 dark:text-teal-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">内容与体验（Content & Experiences）</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n Q3 该板块营收增长 6.5% 至 $10.5B，调整后 EBITDA 飙升 29.3% 至 $1.8B。流媒体平台 Peacock 付费订阅增至 4,800 万，电影制片厂受益于强劲院线表现，有效对冲了主题公园业务的短期波动。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-accent-500/15 text-accent-600 dark:text-accent-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">企业服务连接（Business Services Connectivity）</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 面向中小企业与大型企业客户的高速网络连接服务营收同比增长 2.7%，EBITDA 利润率高达 55.9%，展现出极高的盈利质量与客户粘性。\n </p>\n </div>\n </li>\n </ul>\n </div>\n <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n <span class=\"text-slate-500 dark:text-slate-400\">核心战略调整</span>\n <span class=\"font-bold text-cmcblue-600 dark:text-cmcblue-400\">NBCUniversal 与 Sky 资产重组（计划中）</span>\n </div>\n </div>\n </div>\n\n <!-- 核心业务板块矩阵卡片 -->\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-cmcblue-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-cmcblue-500/15 text-cmcblue-600 dark:text-cmcblue-400 text-xs font-bold\">核心现金牛 · 宽带与无线</span>\n <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">高利润率底盘</span>\n </div>\n <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">住宅连接与平台 (Residential C&P)</h3>\n <p class=\"mt-2 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n Xfinity 宽带服务与移动通信业务。通过多业务捆绑降低流失率，无线用户单季大增 36.8 万，成为抵御光纤竞争的重要利器。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-slate-500\">\n EBITDA 利润率 ~38.6% · 无线用户破1000万\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-teal-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">增长引擎 · 媒体与流媒体</span>\n <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">Peacock 达 4800万</span>\n </div>\n <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">媒体与流媒体 (Media & Peacock)</h3>\n <p class=\"mt-2 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n NBCUniversal 旗下媒体矩阵，流媒体 Peacock 付费订阅飙升至 4,800 万。Q3 受益于 FIFA 世界杯等顶级赛事带来强劲的广告与媒体收入。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold\">\n Peacock 订阅 48M · 赛事直播驱动\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-accent-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-accent-500/10 text-accent-600 dark:text-accent-400 text-xs font-bold\">高收益 · 影视与主题公园</span>\n <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">Studios EBITDA +18.6%</span>\n </div>\n <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">制片厂与主题公园 (Studios & Parks)</h3>\n <p class=\"mt-2 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 环球影业凭借强劲的院线票房表现驱动 Studios EBITDA 同比大增 18.6%；主题公园业务在经历门票促销期后依然保持稳定的现金流贡献。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-accent-600 dark:text-accent-400 font-semibold\">\n 电影票房表现亮眼 · 优质 IP 变现\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 二、 行业地位与四重核心护城河 (Industry Position & Moat)\n ========================================================= -->\n <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 02 · Industry Position & Economic Moat</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 行业地位与四重核心护城河：最后一公里宽带网、IP 宇宙与现金流垄断</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">护城河评级：宽护城河 (Wide Moat · 美国最大有线宽带与内容娱乐巨头)</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n <!-- 左侧：四重护城河深度解析 -->\n <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-cmcblue-500/15 text-cmcblue-600 dark:text-cmcblue-400 flex items-center justify-center font-bold text-sm\">01</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">“最后一公里”宽带基础设施垄断</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 覆盖数千万美国家庭的高带宽有线网络（Cable Infrastructure）。尽管面临光纤与FWA分流，其高速固网宽带仍是美国家庭数字生活的绝对基础设施。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-accent-500/15 text-accent-600 dark:text-accent-400 flex items-center justify-center font-bold text-sm\">02</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">NBCUniversal 顶级 IP 与全球娱乐矩阵</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 拥有环球影业、NBC电视网、梦工厂动画及全球主题公园，构筑起从大荧幕、流媒体到线下实景娱乐的闭环 IP 变现生态。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-teal-500/15 text-teal-600 dark:text-teal-400 flex items-center justify-center font-bold text-sm\">03</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">庞大且高度稳定的自由现金流造血能力</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 即使在资本开支高峰期，单季自由现金流依然高达数十亿美元（Q3 FCF达 $4.2B），为持续派息与大规模股票回购提供充足弹药。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm\">04</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">Xfinity 移动通信与宽带交叉捆绑生态</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 通过 MVNO 合作推出的 Xfinity Mobile 业务与宽带套餐深度绑定，大幅降低宽带客户流失率，构建起极强的客户终身价值（LTV）。\n </p>\n </div>\n </div>\n\n <!-- 右侧：五维护城河雷达图 -->\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">电信与媒体行业五维护城河量化雷达图</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">康卡斯特 (CMCSA) vs 传统纯有线电视商 vs 流媒体纯玩家（满分 10 分）</p>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"moatRadarChart\"></canvas>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 三、 同行竞争格局横向对比 (Competitive Landscape)\n ========================================================= -->\n <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-cmcblue-600 dark:text-cmcblue-400\">Section 03 · Global Competitive Landscape</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 同行竞争格局横向对比：全美宽带与流媒体娱乐巨头交锋</h2>\n </div>\n <!-- 交互式筛选按钮 -->\n <div class=\"flex flex-wrap gap-1.5 text-xs no-print\" id=\"comp-filter-group\">\n <button onclick=\"filterCompetitors('all')\" data-filter=\"all\" class=\"comp-filter-btn active px-3 py-1.5 rounded-lg font-semibold bg-cmcblue-500 text-white shadow-sm transition\">全部阵营</button>\n <button onclick=\"filterCompetitors('telecom')\" data-filter=\"telecom\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">宽带与电信运营商</button>\n <button onclick=\"filterCompetitors('media')\" data-filter=\"media\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">流媒体与内容娱乐巨头</button>\n </div>\n </div>\n\n <!-- 横向对比矩阵表格 -->\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n <div class=\"overflow-x-auto\">\n <table class=\"w-full text-left border-collapse\">\n <thead>\n <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n <th class=\"py-4 px-5 min-w-[180px]\">竞争厂商与核心平台</th>\n <th class=\"py-4 px-4 min-w-[130px]\">主营业务与核心定位</th>\n <th class=\"py-4 px-4 min-w-[140px]\">宽带/流媒体用户规模</th>\n <th class=\"py-4 px-4 min-w-[135px]\">营业利润率特征</th>\n <th class=\"py-4 px-5 min-w-[240px]\">核心优劣势与竞争评估</th>\n </tr>\n </thead>\n <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\" id=\"comp-table-body\">\n <tr data-category=\"telecom\" class=\"bg-cmcblue-500/5 dark:bg-cmcblue-500/10 font-medium\">\n <td class=\"py-4 px-5\">\n <div class=\"flex items-center space-x-2\">\n <span class=\"px-2 py-0.5 rounded bg-cmcblue-500 text-white text-[10px] font-extrabold\">行业巨头</span>\n <span class=\"font-bold text-slate-900 dark:text-white\">康卡斯特 Comcast (CMCSA)</span>\n </div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">有线宽带 + NBCU 影视娱乐生态</div>\n </td>\n <td class=\"py-4 px-4 font-semibold text-slate-900 dark:text-white\">宽带接入、无线、制片厂、主题公园</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">宽带千万级用户 · Peacock 48M</td>\n <td class=\"py-4 px-4 font-mono font-bold text-cmcblue-600 dark:text-cmcblue-400\">~18.2% (Q3 经营利润率)</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>连接与内容完美结合：</strong>拥有强大的宽带现金牛与全球顶级IP，当前估值深度低估，安全边际高。\n </td>\n </tr>\n\n <tr data-category=\"telecom\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">特许通讯 Charter Communications (CHTR)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">美国第二大有线电视运营商</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">Spectrum 宽带、有线电视与移动通信</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">数千万有线及宽带连接用户</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~30%+ 较高 EBITDA 利润率</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>纯有线网络运营商：</strong>缺乏类似 NBCU 的庞大好莱坞制片厂与主题公园内容生态，主要依靠纯宽带与移动套餐防守。\n </td>\n </tr>\n\n <tr data-category=\"media\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">华特迪士尼 The Walt Disney Company (DIS)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">全球娱乐与流媒体巨头</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">迪士尼+流媒体、影视制片、主题公园</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-350\">Disney+ 亿级全球订阅用户</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">流媒体板块逐步实现盈利</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>顶级 IP 变现机器：</strong>在主题公园与合家欢 IP 上全球领先，但缺乏类似康卡斯特的宽带基础设施作为高利润现金牛。\n </td>\n </tr>\n </tbody>\n </table>\n </div>\n </div>\n\n <!-- 配套 Chart.js 横向条形图：经营利润率对比 -->\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">全球主要电信与媒体娱乐公司经营利润率（Operating Margin）对比</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">康卡斯特 Q3 经营利润率提升至 18.2%，展现出极强的抗周期盈利质量</p>\n </div>\n <span class=\"text-xs font-semibold text-cmcblue-600 dark:text-cmcblue-400 bg-cmcblue-500/15 px-2.5 py-1 rounded\">稳健的宽带与媒体双核盈利</span>\n </div>\n <div class=\"relative h-60 w-full\">\n <canvas id=\"compMarginChart\"></canvas>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 四、 财务健康度与估值体系解析 (Financial Health & Valuation)\n ========================================================= -->\n <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 04 · Financial Health & Valuation Framework</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 财务健康与估值体系：超 45% 的 DCF 安全边际与高股息回报</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">DCF 盈利内在价值 $45.66 · 预期股息率 5.25%</span>\n </div>\n\n <!-- 1. 财务健康度四大硬核指标卡 -->\n <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-cmcblue-600 dark:text-cmcblue-400 uppercase\">Operating Margin</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">18.2%</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n Q3 营业利润率由去年同期的 16.8% 明显提升至 18.2%，展现出优秀的降本增效成果。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase\">Free Cash Flow</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$4.2B (Q3)</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 单季自由现金流达 $42 亿美元（FCF 利润率 14.4%），全年持续产生海量现金回报股东。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-teal-600 dark:text-teal-400 uppercase\">Dividend Yield</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~5.25%</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 当前市价下预期股息率高达 5.25%，在科技与通信巨头中属于极具吸引力的现金回报标的。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-accent-600 dark:text-accent-400 uppercase\">DCF Margin of Safety</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">+45.8%</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 机构 DCF 盈利模型测算内在价值 $45.66（自由现金流模型显示更高），当前市价严重低估。\n </p>\n </div>\n </div>\n\n <!-- 2. 交互式 Chart.js 财务演进双轴图 -->\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">2023–2026 营收与自由现金流（FCF）演进趋势</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">稳健的营收基数与百亿级自由现金流，构筑起极强的抗周期安全垫</p>\n </div>\n <span class=\"text-xs font-mono font-bold text-cmcblue-600 dark:text-cmcblue-400 bg-cmcblue-500/10 px-2.5 py-1 rounded\">Q3 FCF $4.2B</span>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"valEvolutionChart\"></canvas>\n </div>\n </div>\n\n <!-- 3. 互动式复利推演计算器 -->\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 sm:p-8 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col md:flex-row justify-between md:items-center gap-4 mb-6\">\n <div>\n <h3 class=\"text-lg font-bold text-white\">康卡斯特 (CMCSA) 投资回报与复利推演器</h3>\n <p class=\"text-xs text-slate-400 mt-1\">模拟在不同估值修复空间与股息再投资（DRIP）下的长期持仓市值回报</p>\n </div>\n <span class=\"text-xs px-3 py-1 rounded-full bg-slate-800 text-cmcblue-300 border border-slate-700\">交互式推演模型</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-3 gap-8 items-center\">\n <div class=\"space-y-5\">\n <div>\n <div class=\"flex justify-between text-sm mb-1\">\n <span class=\"text-slate-300\">初始投资本金 (USD)</span>\n <span id=\"invVal\" class=\"font-bold text-white\">$20,000</span>\n </div>\n <input id=\"invSlider\" type=\"range\" min=\"5000\" max=\"200000\" step=\"5000\" value=\"20000\" class=\"w-full accent-cmcblue-400 cursor-pointer\">\n </div>\n <div>\n <div class=\"flex justify-between text-sm mb-1\">\n <span class=\"text-slate-300\">持有年限 (Years)</span>\n <span id=\"yrVal\" class=\"font-bold text-white\">3 年</span>\n </div>\n <input id=\"yrSlider\" type=\"range\" min=\"1\" max=\"10\" step=\"1\" value=\"3\" class=\"w-full accent-cmcblue-400 cursor-pointer\">\n </div>\n <div>\n <div class=\"flex justify-between text-sm mb-1\">\n <span class=\"text-slate-300\">预期年化股价/估值修复增速</span>\n <span id=\"grVal\" class=\"font-bold text-cmcblue-400\">12.0%</span>\n </div>\n <input id=\"grSlider\" type=\"range\" min=\"0\" max=\"25\" step=\"0.5\" value=\"12.0\" class=\"w-full accent-cmcblue-400 cursor-pointer\">\n </div>\n </div>\n\n <div class=\"lg:col-span-2 grid grid-cols-1 sm:grid-cols-3 gap-4\">\n <div class=\"bg-slate-800/90 p-5 rounded-xl border border-slate-700\">\n <div class=\"text-xs text-slate-400\">期末预计总资产市值</div>\n <div id=\"finalBalance\" class=\"text-2xl font-bold text-white mt-2\">$28,092</div>\n <div id=\"totalGainPct\" class=\"text-xs text-cmcblue-400 mt-1\">累计总回报 +40.5%</div>\n </div>\n <div class=\"bg-slate-800/90 p-5 rounded-xl border border-slate-700\">\n <div class=\"text-xs text-slate-400\">期末对应隐含股价</div>\n <div id=\"impliedPrice\" class=\"text-2xl font-bold text-teal-400 mt-2\">$35.35</div>\n <div class=\"text-xs text-slate-400 mt-1\">向 DCF 内核价值 ($45.66) 靠拢</div>\n </div>\n <div class=\"bg-slate-800/90 p-5 rounded-xl border border-slate-700\">\n <div class=\"text-xs text-slate-400\">隐含复合年化回报 (CAGR)</div>\n <div id=\"cagrVal\" class=\"text-2xl font-bold text-amber-400 mt-2\">12.0%</div>\n <div class=\"text-xs text-slate-400 mt-1\">资本增值加 5.25% 高股息率</div>\n </div>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 五、 投资决策与风险配置框架 (Investment Decision & Risk)\n ========================================================= -->\n <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-cmcblue-600 dark:text-cmcblue-400\">Section 05 · Investment Decision & Risk Allocation</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 投资决策与风险配置框架：三情景推演与核心风险评估</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">配置建议：机构组合中的高股息防御与深度价值修复底仓</span>\n </div>\n\n <!-- 1. 三情景估值推演卡片 -->\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-cmcblue-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-cmcblue-500/15 text-cmcblue-600 dark:text-cmcblue-400 text-xs font-bold\">牛市情景 (Bull Case)</span>\n <span class=\"font-mono text-xs font-bold text-cmcblue-600 dark:text-cmcblue-400\">概率：30%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">目标价格：$42.00 – $45.66</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>宽带用户流失见底回稳，无线业务超预期盈利，Peacock 成功实现全面实质性盈利，市场充分认可其现金流价值，估值向 DCF 内在价值回归。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-cmcblue-600 dark:text-cmcblue-400\">\n 潜在上行空间：+65% 至 +80%\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-accent-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-accent-500/15 text-accent-600 dark:text-accent-400 text-xs font-bold\">基准情景 (Base Case)</span>\n <span class=\"font-mono text-xs font-bold text-accent-600 dark:text-accent-400\">概率：50%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">目标价格：$32.00 – $36.00</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>宽带用户小幅流失但 ARPU 持续上升，无线与流媒体亏损收窄抵消部分影响，自由现金流稳定创造，投资者享受 5.25% 股息加稳健资本增值。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-accent-600 dark:text-accent-400\">\n 潜在上行空间：+25% 至 +40%\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">熊市情景 (Bear Case)</span>\n <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">概率：20%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">防御底线：$22.00 – $24.00</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>光纤与 FWA 竞争超预期加剧导致宽带用户流失加速，传统有线电视断网潮扩大，整体营收与 EBITDA 出现阶段性下滑。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n 潜在下行回撤：-10% 至 -15% (受 5.25% 高股息强力托底)\n </div>\n </div>\n </div>\n\n <!-- 2. 四大核心风险评估矩阵 -->\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">四大核心风险评估与机构应对策略</h3>\n <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-rose-500/10 text-rose-600 dark:text-rose-400 text-xs font-bold\">01 · 光纤与 FWA 宽带竞争分流风险</span>\n <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：高</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">固定无线接入与光纤持续渗透</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 竞争对手的激进光纤建设与 FWA 促销（如部分区域低价策略）导致 Q3 国内宽带用户净减少 14.4 万，需密切关注长期宽带基本盘防线。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-amber-500/10 text-amber-600 dark:text-amber-400 text-xs font-bold\">02 · 有线电视用户加速流失（Cord-Cutting）</span>\n <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：中高</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">传统电视业务结构性衰退</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 传统付费电视（Video）用户持续流失（Q3 国内视频用户净减少 27.4 万），传统有线电视打包服务的收入面临结构性压降。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">03 · 资产重组与剥离执行风险</span>\n <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">NBCUniversal 与 Sky 后续分拆不确定性</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 公司计划在 2027 年中进行有线网络与传统媒体资产的潜在分拆重组，大型资产重组过程中的执行摩擦与监管审批需要持续跟踪。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">04 · 流媒体盈利平衡挑战</span>\n <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">Peacock 平台规模化盈利压力</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 尽管 Peacock 付费订阅达 4,800 万，但全球流媒体赛道竞争白热化，内容制作与体育版权成本高昂，持续实现跨周期盈利仍需考验运营能力。\n </p>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 六、 季度基本面跟踪 KPI 交互式核查清单 (Checklist)\n ========================================================= -->\n <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 06 · Quarterly Fundamental Tracking KPIs</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">六、 季度基本面跟踪 KPI 交互式核查清单（Checklist）</h2>\n </div>\n <div class=\"flex items-center space-x-2 no-print\">\n <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-cmcblue-500/15 text-cmcblue-600 dark:text-cmcblue-400 text-xs font-bold\">已核查 3 / 6 项 (50%)</span>\n <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 dark:hover:bg-navy-700 text-xs font-medium text-slate-700 dark:text-slate-300 transition\">重置清单</button>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">\n 点击勾选机构财报追踪已验证达标的核心指标（状态自动本地保存），用高频基本面事实动态校准投资逻辑：\n </p>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5\" id=\"kpi-checklist\">\n <!-- KPI 1 -->\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0066CC] focus:ring-cmcblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. 国内宽带用户净流失速度是否企稳收敛</span>\n <span class=\"text-[11px] font-mono text-cmcblue-600 dark:text-cmcblue-400 font-semibold shrink-0\">宽带基本盘</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 监控每季国内住宅宽带用户净增/净减情况（Q3 净减少 14.4 万），评估光纤与 FWA 竞争的边际变化。\n </p>\n </div>\n </label>\n\n <!-- KPI 2 -->\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0066CC] focus:ring-cmcblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. Xfinity Mobile 无线业务净增用户与渗透率</span>\n <span class=\"text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold shrink-0\">移动业务增长</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 追踪无线线缆用户单季净增（Q3 增加 36.8 万，总数达 1,060 万），评估其对宽带客户的捆绑防御效果。\n </p>\n </div>\n </label>\n\n <!-- KPI 3 -->\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0066CC] focus:ring-cmcblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. Peacock 付费订阅用户规模与亏损收窄进程</span>\n <span class=\"text-[11px] font-mono text-accent-600 dark:text-accent-400 font-semibold shrink-0\">流媒体盈利跟踪</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 监控 Peacock 付费用户（当前 4,800 万）的 ARPU 增长与整体盈利改善进度。\n </p>\n </div>\n </label>\n\n <!-- KPI 4 -->\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0066CC] focus:ring-cmcblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. 单季自由现金流（FCF）保持 $40 亿以上稳健创造</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">现金流造血底线</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 检查每季财务报告中的自由现金流表现（Q3 实际达 $4.2B），确保高额股息与回购资金的安全边际。\n </p>\n </div>\n </label>\n\n <!-- KPI 5 -->\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0066CC] focus:ring-cmcblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. 营业利润率稳定在 17%–19% 黄金区间</span>\n <span class=\"text-[11px] font-mono text-amber-600 dark:text-amber-400 font-semibold shrink-0\">利润率稳定器</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 评估各项业务在成本精简与数字化转型下，综合运营利润率能否持续稳居 17%–19%（Q3 实绩 18.2%）。\n </p>\n </div>\n </label>\n\n <!-- KPI 6 -->\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-6\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0066CC] focus:ring-cmcblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">6. 2027 年资产重组（NBCU/Sky 分拆）最新官方进展</span>\n <span class=\"text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold shrink-0\">重大战略重组</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 跟踪公司关于 2027 年中剥离 NBCUniversal/Sky 传统媒体资产的路线图、监管审批及股东价值释放方案。\n </p>\n </div>\n </label>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 页脚免责声明 (Disclaimer Footer)\n ========================================================= -->\n <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n <span>康卡斯特 Comcast Corporation (NASDAQ: CMCSA) 深度商业与投资价值分析报告 · 机构研究框架版</span>\n <span>数据基准：Q3 2026 财报及 2026 年 11 月市场一致预期与 DCF 模型</span>\n </div>\n <p class=\"leading-relaxed\">\n <strong>免责声明：</strong>本深度研究报告基于公司公开财务报告、SEC 10-Q 文件及市场公开一致预期与 DCF 估值模型整理生成，旨在提供结构化的产业分析与机构估值研究框架。报告中涉及的财务预测、DCF 内在价值测算、三情景估值模型及推演数据均基于特定产业假设，不构成任何具体的证券买卖建议、要约或投资承诺。投资者在做出任何资产配置决策前，应结合自身风险承受能力与独立尽职调查审慎判断。\n </p>\n </footer>\n\n </div>\n </main>\n\n <!-- 交互逻辑与 Chart.js 可视化脚本 -->\n <script>\n function toggleTheme() {\n const html = document.documentElement;\n html.classList.toggle('dark');\n updateChartsTheme();\n }\n\n function toggleMobileMenu() {\n const drawer = document.getElementById('mobile-drawer');\n drawer.classList.toggle('hidden');\n }\n\n const sections = document.querySelectorAll('section[id]');\n const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n window.addEventListener('scroll', () => {\n const scrollTop = window.scrollY;\n const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n let currentId = 'sec-exec';\n sections.forEach(sec => {\n const top = sec.offsetTop - 160;\n if (scrollTop >= top) {\n currentId = sec.getAttribute('id');\n }\n });\n\n navLinks.forEach(link => {\n link.classList.remove('active');\n const numSpan = link.querySelector('span span');\n if (numSpan) {\n numSpan.classList.remove('text-cmcblue-400');\n numSpan.classList.add('text-slate-500');\n }\n if (link.dataset.target === currentId) {\n link.classList.add('active');\n if (numSpan) {\n numSpan.classList.remove('text-slate-500');\n numSpan.classList.add('text-cmcblue-400');\n }\n }\n });\n });\n\n function filterCompetitors(category) {\n document.querySelectorAll('.comp-filter-btn').forEach(btn => {\n if (btn.dataset.filter === category) {\n btn.classList.add('bg-cmcblue-500', 'text-white', 'font-semibold', 'shadow-sm');\n btn.classList.remove('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n } else {\n btn.classList.remove('bg-cmcblue-500', 'text-white', 'font-semibold', 'shadow-sm');\n btn.classList.add('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n }\n });\n\n const rows = document.querySelectorAll('#comp-table-body tr');\n rows.forEach(row => {\n const rowCat = row.dataset.category;\n if (category === 'all' || rowCat === category) {\n row.style.display = '';\n } else {\n row.style.display = 'none';\n }\n });\n }\n\n const KPI_STORAGE_KEY = 'cmcsa_research_kpi_state_v1';\n\n function loadKpiChecklist() {\n try {\n const saved = localStorage.getItem(KPI_STORAGE_KEY);\n if (saved) {\n const stateMap = JSON.parse(saved);\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n if (typeof stateMap[cb.id] === 'boolean') {\n cb.checked = stateMap[cb.id];\n }\n });\n }\n } catch (e) {}\n updateKpiChecklist();\n }\n\n function updateKpiChecklist() {\n const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n const total = checkboxes.length;\n let checkedCount = 0;\n const stateMap = {};\n\n checkboxes.forEach(cb => {\n stateMap[cb.id] = cb.checked;\n if (cb.checked) checkedCount++;\n });\n\n const pct = Math.round((checkedCount / total) * 100);\n document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n try {\n localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n } catch (e) {}\n }\n\n function resetKpiChecklist() {\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n cb.checked = false;\n });\n updateKpiChecklist();\n }\n\n let bizChartInstance = null;\n let radarChartInstance = null;\n let compMarginChartInstance = null;\n let valEvolutionChartInstance = null;\n let currentBizMode = 'revenue';\n\n function getChartColors() {\n const isDark = document.documentElement.classList.contains('dark');\n return {\n text: isDark ? '#CBD5E1' : '#475569',\n grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n };\n }\n\n function initBizChart() {\n const ctx = document.getElementById('bizArchitectureChart').getContext('2d');\n const colors = getChartColors();\n\n const revConfig = {\n type: 'bar',\n data: {\n labels: ['2023', '2024', '2025', 'Q3 2026 (Ann.)'],\n datasets: [\n {\n label: '住宅连接与平台 (Residential C&P) ($B)',\n data: [85.0, 83.5, 81.0, 78.5],\n backgroundColor: '#0066CC',\n borderRadius: 4,\n },\n {\n label: '内容与体验 (Content & Experiences) ($B)',\n data: [43.0, 44.5, 42.0, 41.5],\n backgroundColor: '#3B82F6',\n borderRadius: 4,\n },\n {\n label: '商业服务连接 (Business Services) ($B)',\n data: [9.0, 9.4, 9.8, 10.2],\n backgroundColor: '#06B6D4',\n borderRadius: 4,\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => `${ctx.dataset.label}: $${ctx.parsed.y}B`\n }\n }\n },\n scales: {\n x: {\n stacked: true,\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n stacked: true,\n max: 140,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n }\n }\n }\n };\n\n const segConfig = {\n type: 'bar',\n data: {\n labels: [\n 'Q3 住宅连接营收 ($B)',\n 'Q3 内容与体验营收 ($B)',\n 'Q3 商业服务营收 ($B)',\n 'Q3 调整后 EBITDA ($B)'\n ],\n datasets: [\n {\n label: 'Q3 2026 实绩规模',\n data: [19.66, 10.54, 2.45, 9.11],\n backgroundColor: [\n '#0066CC',\n '#3B82F6',\n '#06B6D4',\n '#10B981'\n ],\n borderRadius: 6,\n barThickness: 28\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: { display: false },\n tooltip: {\n callbacks: {\n label: (ctx) => `Q3 规模: $${ctx.parsed.y}B`\n }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 10, weight: '600' } }\n },\n y: {\n max: 25,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n }\n }\n }\n };\n\n if (bizChartInstance) bizChartInstance.destroy();\n bizChartInstance = new Chart(ctx, currentBizMode === 'revenue' ? revConfig : segConfig);\n }\n\n function switchBizChart(mode) {\n currentBizMode = mode;\n const btnRev = document.getElementById('btn-chart-rev');\n const btnSeg = document.getElementById('btn-chart-seg');\n const titleEl = document.getElementById('biz-chart-title');\n const subEl = document.getElementById('biz-chart-sub');\n\n if (mode === 'revenue') {\n btnRev.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-cmcblue-600 dark:text-cmcblue-400 shadow-sm transition';\n btnSeg.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n titleEl.textContent = '2023–2026 核心板块营收演进与贡献结构';\n subEl.textContent = 'Connectivity & Platforms 与 Content & Experiences 双核驱动';\n } else {\n btnSeg.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-cmcblue-600 dark:text-cmcblue-400 shadow-sm transition';\n btnRev.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n titleEl.textContent = 'Q3 2026 各主要分部营收与调整后 EBITDA 构成';\n subEl.textContent = '有线宽带与内容体验板块贡献稳健现金流与 EBITDA';\n }\n initBizChart();\n }\n\n function initRadarChart() {\n const ctx = document.getElementById('moatRadarChart').getContext('2d');\n const colors = getChartColors();\n\n if (radarChartInstance) radarChartInstance.destroy();\n radarChartInstance = new Chart(ctx, {\n type: 'radar',\n data: {\n labels: [\n '最后一公里宽带网垄断',\n 'NBCU顶级IP与影视主题公园',\n '海量自由现金流造血能力',\n 'Xfinity移动通信交叉捆绑生态',\n '有线网络基础设施规模壁垒'\n ],\n datasets: [\n {\n label: '康卡斯特 Comcast (CMCSA)',\n data: [9.6, 9.5, 9.4, 9.0, 9.7],\n borderColor: '#0066CC',\n backgroundColor: 'rgba(0, 102, 204, 0.22)',\n pointBackgroundColor: '#0066CC',\n borderWidth: 2.5\n },\n {\n label: '传统纯有线电视运营商',\n data: [8.5, 5.0, 7.5, 6.5, 9.0],\n borderColor: '#3B82F6',\n backgroundColor: 'rgba(59, 130, 246, 0.14)',\n pointBackgroundColor: '#3B82F6',\n borderWidth: 1.8\n },\n {\n label: '纯流媒体娱乐玩家',\n data: [3.0, 9.2, 5.5, 4.0, 3.5],\n borderColor: '#94A3B8',\n backgroundColor: 'rgba(148, 163, 184, 0.12)',\n pointBackgroundColor: '#94A3B8',\n borderWidth: 1.5,\n borderDash: [4, 4]\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n }\n },\n scales: {\n r: {\n min: 0,\n max: 10,\n ticks: { display: false, stepSize: 2 },\n grid: { color: colors.grid },\n angleLines: { color: colors.radarAngle },\n pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initCompMarginChart() {\n const ctx = document.getElementById('compMarginChart').getContext('2d');\n const colors = getChartColors();\n\n if (compMarginChartInstance) compMarginChartInstance.destroy();\n compMarginChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: [\n 'Charter Communications (CHTR)',\n 'Comcast 康卡斯特 (CMCSA)',\n 'The Walt Disney Company (DIS)'\n ],\n datasets: [{\n label: '经营利润率 / EBITDA 利润率特征 (%)',\n data: [32.0, 18.2, 16.5],\n backgroundColor: [\n '#3B82F6',\n '#0066CC',\n '#06B6D4'\n ],\n borderRadius: 6,\n barThickness: 26\n }]\n },\n options: {\n indexAxis: 'y',\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: { display: false },\n tooltip: {\n callbacks: {\n label: (ctx) => `利润率特征: ${ctx.parsed.x}%`\n }\n }\n },\n scales: {\n x: {\n max: 40,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n },\n y: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initValEvolutionChart() {\n const ctx = document.getElementById('valEvolutionChart').getContext('2d');\n const colors = getChartColors();\n\n if (valEvolutionChartInstance) valEvolutionChartInstance.destroy();\n valEvolutionChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: ['2023', '2024', '2025', 'Q3 2026 (Ann.)'],\n datasets: [\n {\n type: 'bar',\n label: '全年/年度化总营收 ($B)',\n data: [121.5, 122.5, 121.0, 117.2],\n backgroundColor: 'rgba(0, 102, 204, 0.85)',\n borderRadius: 5,\n barThickness: 28,\n yAxisID: 'y'\n },\n {\n type: 'bar',\n label: '自由现金流 FCF ($B)',\n data: [13.2, 14.1, 15.0, 16.8],\n backgroundColor: 'rgba(16, 185, 129, 0.85)',\n borderRadius: 5,\n barThickness: 28,\n yAxisID: 'y1'\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => `${ctx.dataset.label}: $${ctx.parsed.y}B`\n }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n type: 'linear',\n position: 'left',\n max: 150,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n },\n y1: {\n type: 'linear',\n position: 'right',\n min: 0,\n max: 25,\n grid: { drawOnChartArea: false },\n ticks: { color: '#10B981', font: { size: 11, weight: '600' }, callback: v => '$' + v + 'B' }\n }\n }\n }\n });\n }\n\n function updateChartsTheme() {\n initBizChart();\n initRadarChart();\n initCompMarginChart();\n initValEvolutionChart();\n }\n\n // Calculator Logic\n const invSlider = document.getElementById('invSlider');\n const yrSlider = document.getElementById('yrSlider');\n const grSlider = document.getElementById('grSlider');\n\n function updateCalculator() {\n const principal = parseFloat(invSlider.value);\n const years = parseInt(yrSlider.value);\n const growthRate = parseFloat(grSlider.value) / 100;\n\n document.getElementById('invVal').textContent = '$' + principal.toLocaleString();\n document.getElementById('yrVal').textContent = years + ' 年';\n document.getElementById('grVal').textContent = (growthRate * 100).toFixed(1) + '%';\n\n const finalVal = principal * Math.pow(1 + growthRate, years);\n const totalGain = finalVal - principal;\n const gainPct = (totalGain / principal) * 100;\n const impliedPrice = 25.16 * Math.pow(1 + growthRate * 0.9, years);\n\n document.getElementById('finalBalance').textContent = '$' + Math.round(finalVal).toLocaleString();\n document.getElementById('totalGainPct').textContent = '累计总回报 +' + gainPct.toFixed(1) + '%';\n document.getElementById('impliedPrice').textContent = '$' + impliedPrice.toFixed(2);\n document.getElementById('cagrVal').textContent = (growthRate * 100).toFixed(1) + '%';\n }\n\n [invSlider, yrSlider, grSlider].forEach(el => el.addEventListener('input', updateCalculator));\n\n window.addEventListener('DOMContentLoaded', () => {\n loadKpiChecklist();\n initBizChart();\n initRadarChart();\n initCompMarginChart();\n initValEvolutionChart();\n updateCalculator();\n });\n </script>\n</body>\n</html>\n\"\"\"\n\nwith open(\"cmcsa_research_dashboard.html\", \"w\", encoding=\"utf-8\") as f:\n    f.write(html_content)\n\nprint(\"Generated cmcsa_research_dashboard.html successfully.\")"};
